SELECT test.as_login('db_test_system',$$SELECT set_config('test.c43.delivery',cmd.activate_calloff(current_setting('test.c43.calloff')::uuid)::text,true)$$);
SELECT test.check('C43 gọi hàng active không tạo cọc riêng, giá theo dòng lịch',EXISTS(SELECT 1 FROM core.orders WHERE id=current_setting('test.c43.calloff')::uuid AND status='active') AND NOT EXISTS(SELECT 1 FROM core.deposits WHERE order_id=current_setting('test.c43.calloff')::uuid) AND EXISTS(SELECT 1 FROM core.order_versions WHERE order_id=current_setting('test.c43.calloff')::uuid AND value_basis='lines' AND contract_value_vnd=230000) AND EXISTS(SELECT 1 FROM ledger.qty_balances WHERE order_key=current_setting('test.c43.calloff')::uuid AND bucket='committed' AND qty=10000));
SELECT test.as_login('db_test_buyer',$$SELECT set_config('test.c43.toobig',cmd.create_calloff(current_setting('test.c43.framework')::uuid,'C43-TOOBIG',current_setting('test.c43.callterms')::jsonb,jsonb_build_array(jsonb_build_object('lot_id',(current_setting('test.c43.calllines')::jsonb->0->>'lot_id')::uuid,'qty',100000)))::text,true)$$);
SELECT test.as_login('db_test_system',$$SELECT test.expect_error('C43 khung vượt mức không cam kết lô','SELECT cmd.activate_calloff(current_setting(''test.c43.toobig'')::uuid)','FRAMEWORK_LIMIT_EXCEEDED')$$);
