SELECT test.as_login('db_test_seller',$$SELECT cmd.accept_offer(current_setting('test.c43.offer')::uuid)$$);
SELECT set_config('test.c43.groupdata',jsonb_build_object('code','C43-GROUP','demand_id',(SELECT id FROM core.demands WHERE code='CMD-DEMAND'),'product_id',(SELECT id FROM core.products WHERE code='XOAI_CAT_CHU'),'grade_code','L1','total_qty',1000000,'unit_price_vnd',23000,'all_or_nothing',true,'cutoff_at',now()+interval '1 hour')::text,true);
SELECT test.as_login('db_test_buyer',$$SELECT set_config('test.c43.group',cmd.create_group(current_setting('test.c43.groupdata')::jsonb)::text,true)$$);
SELECT set_config('test.c43.groupterms',(SELECT (to_jsonb(v)-ARRAY['created_at','write_xid','amendment_id'])||jsonb_build_object('qty_min',1000000,'qty_max',1000000,'contract_value_vnd',23000000,'deposit_basis_vnd',23000000,'deposit_vnd',6900000,'fee_bps',p.first_order_fee_bps,'fee_floor_vnd',p.fee_floor_vnd,'fee_cap_vnd',p.fee_cap_vnd,'shortfall_penalty_bps',pol.shortfall_penalty_bps,'deposit_bps',pol.deposit_bps,'delivery_window',tstzrange(now()+interval '2 days',now()+interval '3 days')) FROM core.order_versions v JOIN ref.plans p ON p.code=coalesce((SELECT plan_code FROM core.subscriptions WHERE org_id=test.org('TC-M01') AND active_during@>now() LIMIT 1),'free') JOIN core.policy_versions pol ON pol.id=(SELECT id FROM core.policy_versions WHERE effective_from<=now() ORDER BY effective_from DESC LIMIT 1) WHERE v.order_id=test.id('C43GROUPLOT'))::text,true);
SELECT set_config('test.c43.parts',jsonb_build_array(jsonb_build_object('offer_id',current_setting('test.c43.offer')::uuid,'code','C43-GROUP-PART','terms',current_setting('test.c43.groupterms')::jsonb,'document',test.command_doc('C43-GROUP-PART-DOC')))::text,true);
