SELECT test.check('C43 chốt nhóm đồng thời cho các phần chờ cọc',EXISTS(SELECT 1 FROM core.group_orders WHERE id=current_setting('test.c43.group')::uuid AND status='executing') AND EXISTS(SELECT 1 FROM core.orders WHERE id=current_setting('test.c43.part')::uuid AND status='awaiting_deposit') AND EXISTS(SELECT 1 FROM core.deposits WHERE order_id=current_setting('test.c43.part')::uuid AND expected_fee_vnd=(SELECT group_fee_vnd FROM core.group_orders WHERE id=current_setting('test.c43.group')::uuid)));
-- Hết hạn trả lời tiền: status và action dùng lại được, không tự cộng tiền hay nhân việc.
SELECT test.context(NULL,NULL,'system');
INSERT INTO core.deadlines(id,kind,entity,entity_id,order_id,due_at,created_at) SELECT test.id('C44-HAN'),'direct_payment_confirm','direct_payment',id,order_id,now()+interval '1 hour',now() FROM core.direct_payments WHERE order_id=test.id('C40SELL') LIMIT 1;
-- Chọn khoản hoàn C40BUY đã nhận đủ sẽ trả action đã kiểm tra, không thay trạng thái.
INSERT INTO core.deadlines(id,kind,entity,entity_id,order_id,due_at,created_at) SELECT test.id('C44-HAN2'),'direct_payment_confirm','direct_payment',id,order_id,now()+interval '1 hour',now() FROM core.direct_payments WHERE code='C40BUY-DIRECT';
SELECT set_config('test.c44.han',test.id('C44-HAN2')::text,true);
SELECT test.as_login('db_test_system',$$SELECT set_config('test.c44.result',cmd.expire_deadline_result(current_setting('test.c44.han')::uuid)::text,true)$$);
SELECT test.as_login('db_test_system',$$SELECT set_config('test.c44.retry',cmd.expire_deadline_result(current_setting('test.c44.han')::uuid)::text,true)$$);
SELECT test.check('C44 hết hạn trả action ổn định và không nhân task',current_setting('test.c44.result')=current_setting('test.c44.retry') AND current_setting('test.c44.result')::jsonb->>'action'='already_satisfied' AND (SELECT count(*)=0 FROM ops.tasks WHERE dedup_key='deadline:'||test.id('C44-HAN2')) AND (SELECT status='fully_received' FROM core.direct_payments WHERE code='C40BUY-DIRECT'));
DELETE FROM cmd.test_clock;
